         THEN N'Review: legacy shared operations span contacts, firewall rules and escalations.'
         WHEN m.source IN (N'@Administer', N'@Audit', N'@Edit', N'@Export') THEN N'Compatibility with an existing role right.'
         ELSE N'Explicit compatibility mapping; source permissions remain required.' END AS ReviewNote
FROM [iam].[AppRole] r CROSS JOIN OPENJSON(@mapping) WITH (source nvarchar(120), target nvarchar(120)) m
WHERE (EXISTS (SELECT 1 FROM [iam].[AppRolePermission] p WHERE p.AppRoleId=r.Id AND p.Resource+N':'+p.Action=m.source)
    OR m.source=N'@Administer' AND (r.Rights & 128)=128 OR m.source=N'@Audit' AND (r.Rights & 64)=64 OR m.source=N'@Edit' AND (r.Rights & 1)=1 OR m.source=N'@Export' AND (r.Rights & 16)=16)
    AND NOT EXISTS (SELECT 1 FROM [iam].[AppRolePermission] p WHERE p.AppRoleId=r.Id AND p.Resource+N':'+p.Action=m.target)
ORDER BY RoleName, ProposedGrant;
